set check_function_bodies = off;

CREATE OR REPLACE FUNCTION public.cancel_sales_invoice_atomic(p_sale_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_sale     public.sales%ROWTYPE;
  v_label    TEXT;
  v_reason   TEXT;
  v_line     RECORD;
  v_demand   JSONB := '{}'::jsonb;
  v_key      TEXT;
  v_units    NUMERIC;
  v_cash     INTEGER := 0;
  v_journals INTEGER := 0;
BEGIN
  IF p_sale_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Satış ID göndərilməyib';
  END IF;

  IF NOT (public.require_permission('can_delete_sales')
          OR public.require_permission('can_edit_sales')) THEN
    RAISE EXCEPTION 'forbidden'
      USING ERRCODE = '42501', MESSAGE = 'Satış ləğvi üçün icazəniz yoxdur';
  END IF;

  SELECT * INTO v_sale FROM public.sales WHERE id = p_sale_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE = 'P0002', MESSAGE = 'Satış fakturası tapılmadı';
  END IF;

  v_label := COALESCE(NULLIF(trim(v_sale.doc_no), ''), NULLIF(trim(v_sale.invoice_number), ''), p_sale_id::text);
  v_reason := COALESCE(NULLIF(trim(p_reason), ''), format('Satış fakturası %s ləğv edildi', v_label));

  IF v_sale.status IN ('cancelled', 'void', 'voided') THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = format('%s artıq ləğv edilib', v_label);
  END IF;

  -- A draft never moved stock, cash or the ledger.
  IF v_sale.status = 'draft' THEN
    UPDATE public.sales SET status = 'cancelled', remaining_balance = 0 WHERE id = p_sale_id;
    RETURN jsonb_build_object('success', true, 'sale_id', p_sale_id, 'doc_no', v_label,
                              'was', 'draft');
  END IF;

  -- 1. Stock lines (not dimensional, not services): give the quantity back,
  --    exploding kits through their BOM exactly as posting did.
  FOR v_line IN
    SELECT si.id, si.product_id, si.quantity, si.warehouse_id, si.unit, p.name AS product_name
    FROM public.sale_items si
    JOIN public.products p ON p.id = si.product_id
    WHERE si.sale_id = p_sale_id
      AND COALESCE(si.quantity, 0) > 0
      AND NULLIF(btrim(si.polywood_sale_mode), '') IS NULL
      AND COALESCE(si.sale_item_type, 'standard') <> 'service'
      AND NOT COALESCE(p.is_service, false)
  LOOP
    v_demand := public.merge_stock_demand(v_demand, v_line.product_id, v_line.quantity);

    INSERT INTO public.stock_movements (
      product_id, warehouse_id, movement_type, quantity, unit,
      reference_type, reference_id, source_line_id, description, created_by
    )
    VALUES (
      v_line.product_id, v_line.warehouse_id, 'in', v_line.quantity,
      COALESCE(v_line.unit, 'Ədəd'), 'sale_void', p_sale_id, v_line.id,
      format('Ləğv: satış fakturası %s — %s', v_label, COALESCE(v_line.product_name, '')),
      auth.uid()
    );
  END LOOP;

  FOR v_key IN SELECT jsonb_object_keys(v_demand)
  LOOP
    UPDATE public.products
    SET stock = COALESCE(stock, 0) + (v_demand->>v_key)::numeric
    WHERE id = v_key::uuid;
  END LOOP;

  -- 2. Dimensional (Polywood) lines: put the cut pieces back.
  FOR v_line IN
    SELECT si.*, COALESCE(p.full_sheet_length_m, p.base_length, 4) AS sheet_length_m
    FROM public.sale_items si
    JOIN public.products p ON p.id = si.product_id
    WHERE si.sale_id = p_sale_id
      AND NULLIF(btrim(si.polywood_sale_mode), '') IS NOT NULL
  LOOP
    IF v_line.polywood_cut_details IS NOT NULL THEN
      PERFORM public.rollback_mixed_dimensional_sale(v_line.id);
      IF v_line.warehouse_id IS NOT NULL THEN
        UPDATE public.products
        SET stock = (
          SELECT COALESCE(SUM(length_m), 0)
          FROM public.polywood_pieces
          WHERE product_id = v_line.product_id
            AND warehouse_id = v_line.warehouse_id
            AND status = 'available'
        )
        WHERE id = v_line.product_id;
      END IF;
    ELSE
      -- Sold before piece tracking: restore the metres.
      v_units := CASE
        WHEN v_line.polywood_sale_mode = 'full_sheet'
          THEN COALESCE(v_line.quantity, 0) * v_line.sheet_length_m
        WHEN v_line.sale_item_type = 'dimensional'
          THEN COALESCE(v_line.polywood_length_m, v_line.quantity, 0) * GREATEST(COALESCE(v_line.piece_count, 1), 1)
        ELSE COALESCE(v_line.polywood_length_m, v_line.quantity, 0)
      END;
      IF v_units > 0 THEN
        UPDATE public.products SET stock = COALESCE(stock, 0) + v_units WHERE id = v_line.product_id;
      END IF;
    END IF;
  END LOOP;

  -- 3. FIFO: give consumed quantities back to their layers.
  UPDATE public.inventory_batches b
  SET remaining_qty = b.remaining_qty + c.qty
  FROM (
    SELECT batch_id, SUM(quantity) AS qty
    FROM public.inventory_batch_consumptions
    WHERE sale_id = p_sale_id AND batch_id IS NOT NULL
    GROUP BY batch_id
  ) c
  WHERE b.id = c.batch_id;

  DELETE FROM public.inventory_batch_consumptions WHERE sale_id = p_sale_id;
  UPDATE public.sale_items SET cogs_amount = 0 WHERE sale_id = p_sale_id;

  -- 4. Cash received for the invoice (and paid additional expenses).
  v_cash := public.reverse_document_cash_transactions('sale', p_sale_id, v_label, v_reason);

  -- 5. Pending warehouse slips for the invoice are void with it.
  DELETE FROM public.warehouse_slips
  WHERE source_type = 'sale' AND source_document_id = p_sale_id;

  -- 6. Invoice and COGS journals.
  v_journals := public.reverse_document_journals(p_sale_id, v_reason);

  UPDATE public.sales
  SET status = 'cancelled',
      remaining_balance = 0,
      total_cogs = 0
  WHERE id = p_sale_id;

  PERFORM public.refresh_customer_ar_balance(v_sale.customer_id);

  RETURN jsonb_build_object(
    'success', true,
    'sale_id', p_sale_id,
    'doc_no', v_label,
    'was', 'posted',
    'cash_reversed', v_cash,
    'journals_reversed', v_journals
  );
END;
$function$;

CREATE OR REPLACE FUNCTION public.create_sale_atomic(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_header JSONB;
  v_items JSONB;
  v_payments JSONB;
  v_decrement_stock BOOLEAN := true;
  v_customer_id UUID;
  v_customer_name TEXT;
  v_sale_id UUID;
  v_doc_no TEXT;
  v_total_amount NUMERIC;
  v_paid_amount NUMERIC;
  v_remaining NUMERIC;
  v_item JSONB;
  v_pay JSONB;
  v_product_id UUID;
  v_qty NUMERIC;
  v_stock NUMERIC;
  v_account_id UUID;
  v_pay_amount NUMERIC;
  v_pay_method TEXT;
  v_skip_stock BOOLEAN;
  v_polywood_mode TEXT;
  v_item_ids JSONB := '[]'::jsonb;
  v_item_id UUID;
  v_idx INT := 0;
  v_stock_demand JSONB := '{}'::jsonb;
  v_key TEXT;
BEGIN
  IF NOT public.require_permission('can_edit_sales') THEN
    RAISE EXCEPTION 'forbidden'
      USING ERRCODE = '42501',
            MESSAGE = 'Satış yaratmaq üçün icazəniz yoxdur';
  END IF;

  IF p_payload IS NULL THEN
    RAISE EXCEPTION 'invalid_payload'
      USING ERRCODE = '22023',
            MESSAGE = 'Satış məlumatları göndərilməyib';
  END IF;

  v_header := COALESCE(p_payload->'header', '{}'::jsonb);
  v_items := COALESCE(p_payload->'items', '[]'::jsonb);
  v_payments := COALESCE(p_payload->'payments', '[]'::jsonb);

  IF jsonb_typeof(v_items) <> 'array' OR jsonb_array_length(v_items) = 0 THEN
    RAISE EXCEPTION 'items_required'
      USING ERRCODE = '22023',
            MESSAGE = 'Ən azı bir satış sətri tələb olunur';
  END IF;

  IF (p_payload ? 'decrement_stock') THEN
    v_decrement_stock := COALESCE((p_payload->>'decrement_stock')::boolean, true);
  END IF;

  v_customer_id := NULLIF(v_header->>'customer_id', '')::uuid;
  IF v_customer_id IS NULL THEN
    RAISE EXCEPTION 'customer_required'
      USING ERRCODE = '22023',
            MESSAGE = 'Müştəri seçilməlidir';
  END IF;

  SELECT COALESCE(NULLIF(trim(full_name), ''), NULLIF(trim(name), ''), NULLIF(trim(company_name), ''), '')
  INTO v_customer_name
  FROM customers
  WHERE id = v_customer_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'customer_not_found'
      USING ERRCODE = 'P0002',
            MESSAGE = 'Müştəri tapılmadı';
  END IF;

  v_total_amount := COALESCE(NULLIF(v_header->>'total_amount', '')::numeric, 0);
  v_paid_amount := COALESCE(NULLIF(v_header->>'paid_amount', '')::numeric, 0);
  v_remaining := GREATEST(
    COALESCE(
      NULLIF(v_header->>'remaining_balance', '')::numeric,
      v_total_amount - v_paid_amount
    ),
    0
  );

  IF v_paid_amount > v_total_amount + 0.0001 THEN
    RAISE EXCEPTION 'overpaid'
      USING ERRCODE = '22023',
            MESSAGE = 'Ödənilən məbləğ ümumi məbləğdən böyük ola bilməz';
  END IF;

  -- Aggregate stock demand per product (standard lines only)
  IF v_decrement_stock THEN
    FOR v_item IN SELECT value FROM jsonb_array_elements(v_items)
    LOOP
      v_product_id := NULLIF(v_item->>'product_id', '')::uuid;
      v_qty := COALESCE(NULLIF(v_item->>'quantity', '')::numeric, 0);
      v_polywood_mode := NULLIF(trim(v_item->>'polywood_sale_mode'), '');
      v_skip_stock := COALESCE((v_item->>'skip_stock')::boolean, false);

      IF v_product_id IS NULL OR v_qty <= 0 OR v_polywood_mode IS NOT NULL OR v_skip_stock THEN
        CONTINUE;
      END IF;

      v_key := v_product_id::text;
      v_stock_demand := jsonb_set(
        v_stock_demand,
        ARRAY[v_key],
        to_jsonb(COALESCE((v_stock_demand->>v_key)::numeric, 0) + v_qty),
        true
      );
    END LOOP;

    FOR v_key IN SELECT jsonb_object_keys(v_stock_demand)
    LOOP
      v_product_id := v_key::uuid;
      v_qty := COALESCE((v_stock_demand->>v_key)::numeric, 0);

      SELECT stock INTO v_stock
      FROM products
      WHERE id = v_product_id
      FOR UPDATE;

      IF NOT FOUND THEN
        RAISE EXCEPTION 'product_not_found'
          USING ERRCODE = 'P0002',
                MESSAGE = 'Məhsul tapılmadı: ' || v_key;
      END IF;

      IF COALESCE(v_stock, 0) + 0.000001 < v_qty THEN
        RAISE EXCEPTION 'insufficient_stock'
          USING ERRCODE = '22023',
                MESSAGE = format(
                  'Stok kifayət etmir (məhsul %s, tələb: %s, mövcud: %s)',
                  v_key,
                  trim(to_char(v_qty, 'FM999999990.00')),
                  trim(to_char(COALESCE(v_stock, 0), 'FM999999990.00'))
                );
      END IF;
    END LOOP;
  END IF;

  -- Validate payment accounts before writing
  IF jsonb_typeof(v_payments) = 'array' THEN
    FOR v_pay IN SELECT value FROM jsonb_array_elements(v_payments)
    LOOP
      v_pay_amount := COALESCE(NULLIF(v_pay->>'amount', '')::numeric, 0);
      IF v_pay_amount <= 0 THEN
        CONTINUE;
      END IF;

      v_account_id := NULLIF(v_pay->>'account_id', '')::uuid;
      IF v_account_id IS NULL THEN
        RAISE EXCEPTION 'account_required'
          USING ERRCODE = '22023',
                MESSAGE = 'Ödəniş üçün kassa/bank hesabı seçilməlidir';
      END IF;

      PERFORM id FROM accounts WHERE id = v_account_id;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'account_not_found'
          USING ERRCODE = 'P0002',
                MESSAGE = 'Seçilmiş kassa/bank hesabı tapılmadı';
      END IF;
    END LOOP;
  END IF;

  v_doc_no := NULLIF(trim(v_header->>'doc_no'), '');
  IF v_doc_no IS NULL THEN
    v_doc_no := 'SF-' || to_char(CURRENT_DATE, 'YYYY') || '-' || floor(10000 + random() * 90000)::int;
  END IF;

  INSERT INTO sales (
    doc_no,
    invoice_number,
    doc_date,
    customer_id,
    customer_name,
    seller_id,
    seller_name,
    warehouse_name,
    subtotal,
    discount_total,
    vat_total,
    total_amount,
    paid_amount,
    remaining_balance,
    delivery_address,
    delivery_type,
    delivery_fee,
    note,
    notes,
    payments,
    created_at
  )
  VALUES (
    v_doc_no,
    COALESCE(NULLIF(trim(v_header->>'invoice_number'), ''), v_doc_no),
    COALESCE(NULLIF(v_header->>'doc_date', '')::date, CURRENT_DATE),
    v_customer_id,
    COALESCE(NULLIF(trim(v_header->>'customer_name'), ''), v_customer_name),
    NULLIF(v_header->>'seller_id', '')::uuid,
    NULLIF(trim(v_header->>'seller_name'), ''),
    NULLIF(trim(v_header->>'warehouse_name'), ''),
    COALESCE(NULLIF(v_header->>'subtotal', '')::numeric, 0),
    COALESCE(NULLIF(v_header->>'discount_total', '')::numeric, 0),
    COALESCE(NULLIF(v_header->>'vat_total', '')::numeric, 0),
    v_total_amount,
    v_paid_amount,
    v_remaining,
    NULLIF(trim(v_header->>'delivery_address'), ''),
    COALESCE(NULLIF(trim(v_header->>'delivery_type'), ''), 'free'),
    COALESCE(NULLIF(v_header->>'delivery_fee', '')::numeric, 0),
    NULLIF(trim(v_header->>'note'), ''),
    NULLIF(trim(v_header->>'notes'), ''),
    COALESCE(v_header->'payments', v_payments, '[]'::jsonb),
    COALESCE(NULLIF(v_header->>'created_at', '')::timestamptz, NOW())
  )
  RETURNING id INTO v_sale_id;

  -- Insert line items
  FOR v_item IN SELECT value FROM jsonb_array_elements(v_items)
  LOOP
    INSERT INTO sale_items (
      sale_id,
      product_id,
      product_code,
      product_name,
      warehouse_id,
      warehouse_name,
      quantity,
      unit,
      unit_price,
      discount_percent,
      vat_rate,
      line_total,
      extra_info,
      polywood_sale_mode,
      polywood_length_m
    )
    VALUES (
      v_sale_id,
      NULLIF(v_item->>'product_id', '')::uuid,
      NULLIF(trim(v_item->>'product_code'), ''),
      NULLIF(trim(v_item->>'product_name'), ''),
      NULLIF(v_item->>'warehouse_id', '')::uuid,
      NULLIF(trim(v_item->>'warehouse_name'), ''),
      COALESCE(NULLIF(v_item->>'quantity', '')::numeric, 0),
      COALESCE(NULLIF(trim(v_item->>'unit'), ''), 'Ədəd'),
      COALESCE(NULLIF(v_item->>'unit_price', '')::numeric, 0),
      COALESCE(NULLIF(v_item->>'discount_percent', '')::numeric, 0),
      COALESCE(NULLIF(v_item->>'vat_rate', '')::numeric, 0),
      COALESCE(
        NULLIF(v_item->>'line_total', '')::numeric,
        NULLIF(v_item->>'total', '')::numeric,
        0
      ),
      NULLIF(trim(v_item->>'extra_info'), ''),
      NULLIF(trim(v_item->>'polywood_sale_mode'), ''),
      NULLIF(v_item->>'polywood_length_m', '')::numeric
    )
    RETURNING id INTO v_item_id;

    v_item_ids := v_item_ids || jsonb_build_array(
      jsonb_build_object(
        'index', v_idx,
        'id', v_item_id,
        'product_id', NULLIF(v_item->>'product_id', '')::uuid,
        'polywood_sale_mode', NULLIF(trim(v_item->>'polywood_sale_mode'), '')
      )
    );
    v_idx := v_idx + 1;
  END LOOP;

  -- Deduct aggregated stock
  IF v_decrement_stock THEN
    FOR v_key IN SELECT jsonb_object_keys(v_stock_demand)
    LOOP
      v_product_id := v_key::uuid;
      v_qty := COALESCE((v_stock_demand->>v_key)::numeric, 0);

      UPDATE products
      SET stock = COALESCE(stock, 0) - v_qty
      WHERE id = v_product_id;
    END LOOP;
  END IF;

  -- Cash payments: transactions + account balance
  IF jsonb_typeof(v_payments) = 'array' THEN
    FOR v_pay IN SELECT value FROM jsonb_array_elements(v_payments)
    LOOP
      v_pay_amount := COALESCE(NULLIF(v_pay->>'amount', '')::numeric, 0);
      IF v_pay_amount <= 0 THEN
        CONTINUE;
      END IF;

      v_account_id := NULLIF(v_pay->>'account_id', '')::uuid;
      v_pay_method := COALESCE(NULLIF(trim(v_pay->>'method'), ''), 'Ödəniş');

      SELECT balance INTO v_stock
      FROM accounts
      WHERE id = v_account_id
      FOR UPDATE;

      INSERT INTO transactions (account_id, type, amount, category, notes)
      VALUES (
        v_account_id,
        'Mədaxil',
        v_pay_amount,
        'Satış Ödənişi',
        format('Satış fakturası %s — %s', v_doc_no, v_pay_method)
      );

      UPDATE accounts
      SET balance = COALESCE(v_stock, 0) + v_pay_amount
      WHERE id = v_account_id;
    END LOOP;
  END IF;

  -- Accounts receivable on customer master
  IF v_remaining > 0.0001 THEN
    SELECT balance INTO v_stock
    FROM customers
    WHERE id = v_customer_id
    FOR UPDATE;

    UPDATE customers
    SET balance = COALESCE(v_stock, 0) + v_remaining
    WHERE id = v_customer_id;
  END IF;

  RETURN jsonb_build_object(
    'sale_id', v_sale_id,
    'doc_no', v_doc_no,
    'items', v_item_ids
  );
END;
$function$;

CREATE OR REPLACE FUNCTION public.fifo_deplete_sale_item(p_sale_item_id uuid, p_product_id uuid, p_quantity numeric, p_sale_id uuid)
 RETURNS numeric
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_is_composite BOOLEAN := false;
  v_bom RECORD;
  v_component_qty NUMERIC;
  v_line_cogs NUMERIC := 0;
  v_component_cogs NUMERIC;
BEGIN
  IF p_product_id IS NULL OR COALESCE(p_quantity, 0) <= 0 THEN
    RETURN 0;
  END IF;

  SELECT COALESCE(is_composite, false)
  INTO v_is_composite
  FROM public.products
  WHERE id = p_product_id;

  IF COALESCE(v_is_composite, false) THEN
    FOR v_bom IN
      SELECT component_product_id, quantity
      FROM public.product_bom
      WHERE parent_product_id = p_product_id
      ORDER BY component_product_id
    LOOP
      v_component_qty := COALESCE(p_quantity, 0) * COALESCE(v_bom.quantity, 1);
      v_component_cogs := public.fifo_deplete_product(
        v_bom.component_product_id,
        v_component_qty,
        p_sale_id,
        p_sale_item_id
      );
      v_line_cogs := v_line_cogs + COALESCE(v_component_cogs, 0);
    END LOOP;
  ELSE
    v_line_cogs := public.fifo_deplete_product(
      p_product_id,
      p_quantity,
      p_sale_id,
      p_sale_item_id
    );
  END IF;

  RETURN ROUND(COALESCE(v_line_cogs, 0), 2);
END;
$function$;

CREATE OR REPLACE FUNCTION public.next_sales_doc_no(p_prefix text DEFAULT 'SS'::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_year INT := EXTRACT(YEAR FROM CURRENT_DATE)::INT;
  v_no INT;
  v_prefix TEXT := COALESCE(NULLIF(trim(p_prefix), ''), 'SS');
  v_doc TEXT;
  v_attempts INT := 0;
BEGIN
  LOOP
    INSERT INTO public.document_number_counters (doc_type, year, last_no)
    VALUES ('sales_invoice', v_year, 1)
    ON CONFLICT (doc_type, year)
    DO UPDATE SET last_no = public.document_number_counters.last_no + 1
    RETURNING last_no INTO v_no;

    v_doc := v_prefix || '-' || v_year::TEXT || '-' || lpad(v_no::TEXT, 5, '0');

    EXIT WHEN NOT EXISTS (
      SELECT 1
      FROM public.sales s
      WHERE s.doc_no = v_doc
         OR s.invoice_number = v_doc
    );

    v_attempts := v_attempts + 1;
    IF v_attempts > 10000 THEN
      RAISE EXCEPTION 'doc_no_exhausted'
        USING ERRCODE = 'P0001',
              MESSAGE = 'Satış sənəd nömrəsi yaradıla bilmədi';
    END IF;
  END LOOP;

  RETURN v_doc;
END;
$function$;

CREATE OR REPLACE FUNCTION public.peek_next_sales_doc_no(p_prefix text DEFAULT 'SS'::text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_year INT := EXTRACT(YEAR FROM CURRENT_DATE)::INT;
  v_no INT;
  v_prefix TEXT := COALESCE(NULLIF(trim(p_prefix), ''), 'SS');
BEGIN
  SELECT last_no INTO v_no
  FROM public.document_number_counters
  WHERE doc_type = 'sales_invoice' AND year = v_year;

  RETURN v_prefix || '-' || v_year::TEXT || '-' || lpad((COALESCE(v_no, 0) + 1)::TEXT, 5, '0');
END;
$function$;

CREATE OR REPLACE FUNCTION public.post_sale(p_customer_id uuid, p_warehouse_id uuid, p_seller_id uuid, p_account_id uuid, p_items jsonb, p_paid_amount numeric, p_notes text DEFAULT ''::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_sale_id UUID;
    v_doc_no TEXT;
    v_subtotal NUMERIC := 0;
    v_total_vat NUMERIC := 0;
    v_grand_total NUMERIC := 0;
    v_item JSONB;
    v_product_id UUID;
    v_qty NUMERIC;
    v_unit_price NUMERIC;
    v_category_id UUID;
    v_current_stock NUMERIC;
    v_line_total NUMERIC;
    v_remaining_balance NUMERIC;
BEGIN
    -- ۱. تولید شماره سند ترتیبی و یکتا (مثال: INV-1001)
    SELECT 'INV-' || LPAD((COALESCE(MAX(CAST(SUBSTRING(doc_no FROM 5) AS INTEGER)), 1000) + 1)::TEXT, 6, '0')
    INTO v_doc_no
    FROM sales
    WHERE doc_no LIKE 'INV-%';

    -- ۲. محاسبه مبالغ کل بر اساس اقلام
    FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
    LOOP
        v_qty := (v_item->>'qty')::NUMERIC;
        v_unit_price := (v_item->>'unit_price')::NUMERIC;
        v_subtotal := v_subtotal + (v_qty * v_unit_price);
    END LOOP;

    v_grand_total := v_subtotal; -- در صورت داشتن ارزش افزوده سیستمیک قابل اضافه شدن است
    v_remaining_balance := v_grand_total - p_paid_amount;

    -- ۳. ایجاد هدر فاکتور فروش
    INSERT INTO sales (
        doc_no, customer_id, warehouse_id, seller_id, 
        subtotal, grand_total, paid_amount, remaining_balance, 
        notes, status, created_at
    ) VALUES (
        v_doc_no, p_customer_id, p_warehouse_id, p_seller_id,
        v_subtotal, v_grand_total, p_paid_amount, v_remaining_balance,
        p_notes, 'completed', NOW()
    )
    RETURNING id INTO v_sale_id;

    -- ۴. پردازش تک‌تک اقلام، بررسی سقف موجودی و کسر از انبار
    FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
    LOOP
        v_product_id := (v_item->>'product_id')::UUID;
        v_qty := (v_item->>'qty')::NUMERIC;
        v_unit_price := (v_item->>'unit_price')::NUMERIC;
        v_category_id := (v_item->>'category_id')::UUID;
        v_line_total := v_qty * v_unit_price;

        -- قفل کردن ردیف موجودی انبار جهت جلوگیری از همزمانی (Race Condition)
        SELECT stock INTO v_current_stock
        FROM warehouse_stock
        WHERE warehouse_id = p_warehouse_id AND product_id = v_product_id
        FOR UPDATE;

        IF v_current_stock IS NULL OR v_current_stock < v_qty THEN
            RAISE EXCEPTION 'موجودی کالا (ID: %) در انبار کافی نیست. موجودی فعلی: %', v_product_id, COALESCE(v_current_stock, 0);
        END IF;

        -- ثبت ردیف فاکتور
        INSERT INTO sales_items (
            sale_id, product_id, category_id, qty, unit_price, total_price
        ) VALUES (
            v_sale_id, v_product_id, v_category_id, v_qty, v_unit_price, v_line_total
        );

        -- کسر از جدول موجودی انبار
        UPDATE warehouse_stock
        SET stock = stock - v_qty, updated_at = NOW()
        WHERE warehouse_id = p_warehouse_id AND product_id = v_product_id;

        -- ثبت گردش انبار (Stock Movement Log)
        INSERT INTO stock_movements (
            warehouse_id, product_id, reference_type, reference_id, qty_change
        ) VALUES (
            p_warehouse_id, v_product_id, 'sale', v_sale_id, -v_qty
        );
    END LOOP;

    -- ۵. به‌روزرسانی مانده بدهی مشتری (AR)
    UPDATE customers
    SET balance = balance + v_remaining_balance,
        updated_at = NOW()
    WHERE id = p_customer_id;

    -- ۶. ثبت دریافتی در صندوق/بانک (در صورت پرداخت نقدی)
    IF p_paid_amount > 0 THEN
        IF p_account_id IS NULL THEN
            RAISE EXCEPTION 'حساب دریافتی (صندوق/بانک) مشخص نشده است.';
        END IF;

        INSERT INTO transactions (
            account_id, reference_type, reference_id, 
            type, amount, party_id, notes
        ) VALUES (
            p_account_id, 'sale_payment', v_sale_id, 
            'inflow', p_paid_amount, p_customer_id, 'دریافتی بابت فاکتور ' || v_doc_no
        );

        UPDATE accounts
        SET balance = balance + p_paid_amount,
            updated_at = NOW()
        WHERE id = p_account_id;
    END IF;

    RETURN v_sale_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.post_sale_cogs_journal(p_sale_id uuid, p_doc_no text, p_total_cogs numeric, p_idempotency text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_amount NUMERIC := ROUND(COALESCE(p_total_cogs, 0), 2);
BEGIN
  IF v_amount <= 0 THEN
    RETURN NULL;
  END IF;

  RETURN public.create_journal_entry(
    jsonb_build_object(
      'document_type', 'sale_cogs',
      'document_id', p_sale_id,
      'source_type', 'sale_cogs',
      'source_id', p_sale_id,
      'idempotency_key', COALESCE(p_idempotency, 'sale_cogs:' || p_sale_id::text),
      'description', format('Satış COGS — %s', COALESCE(p_doc_no, p_sale_id::text)),
      'memo', format('Satış COGS — %s', COALESCE(p_doc_no, p_sale_id::text)),
      'lines', jsonb_build_array(
        jsonb_build_object(
          'account_code', '5000',
          'debit', v_amount,
          'credit', 0,
          'line_memo', 'Maya dəyəri (COGS)'
        ),
        jsonb_build_object(
          'account_code', '1300',
          'debit', 0,
          'credit', v_amount,
          'line_memo', 'Anbar ehtiyatları'
        )
      )
    )
  );
END;
$function$;

CREATE OR REPLACE FUNCTION public.post_sale_invoice_gl_journal(p_sale_id uuid, p_doc_no text, p_total numeric, p_customer_id uuid, p_idempotency text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_partner_id UUID;
BEGIN
  v_partner_id := public.resolve_unified_partner_id(p_customer_id, NULL);

  RETURN public.create_journal_entry(
    jsonb_build_object(
      'document_type', 'invoice',
      'document_id', p_sale_id,
      'source_type', 'invoice',
      'source_id', p_sale_id,
      'idempotency_key', COALESCE(p_idempotency, 'sale_invoice:' || p_sale_id::text),
      'description', format('Satış fakturası %s', p_doc_no),
      'memo', format('Satış fakturası %s', p_doc_no),
      'lines', jsonb_build_array(
        jsonb_build_object(
          'account_code', '1200',
          'debit', p_total,
          'credit', 0,
          'partner_type', 'partner',
          'partner_id', v_partner_id,
          'line_memo', 'Müştəri borcları — ' || p_doc_no
        ),
        jsonb_build_object(
          'account_code', '4000',
          'debit', 0,
          'credit', p_total,
          'line_memo', 'Satış gəliri — ' || p_doc_no
        )
      )
    )
  );
END;
$function$;

CREATE OR REPLACE FUNCTION public.post_sales_invoice_draft(p_sale_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_sale RECORD;
  v_items JSONB := '[]'::jsonb;
  v_payments JSONB;
  v_stock_demand JSONB := '{}'::jsonb;
  v_pay JSONB;
  v_pay_amount NUMERIC;
  v_account_id UUID;
  v_pay_method TEXT;
  v_journal_id UUID;
  v_cogs_result JSONB;
  v_total_cogs NUMERIC := 0;
  v_cogs_journal_id UUID;
  v_add_exp_total NUMERIC;
  v_idempotency TEXT;
  v_result JSONB;
  v_event_id UUID;
BEGIN
  IF p_sale_id IS NULL THEN
    RAISE EXCEPTION 'invalid_payload'
      USING ERRCODE = '22023',
            MESSAGE = 'Satış ID göndərilməyib';
  END IF;

  IF NOT (
    public.require_permission('can_edit_sales')
    OR public.require_permission('can_create_invoice')
    OR public.require_permission('can_manage_finance')
  ) THEN
    RAISE EXCEPTION 'forbidden'
      USING ERRCODE = '42501',
            MESSAGE = 'Satış təsdiqləmək üçün icazəniz yoxdur';
  END IF;

  SELECT * INTO v_sale FROM sales WHERE id = p_sale_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'sale_not_found'
      USING ERRCODE = 'P0002',
            MESSAGE = 'Satış sənədi tapılmadı';
  END IF;

  IF v_sale.status = 'posted' THEN
    RAISE EXCEPTION 'already_posted'
      USING ERRCODE = '22023',
            MESSAGE = 'Sənəd artıq təsdiqlənib';
  END IF;

  IF v_sale.status IN ('cancelled', 'void', 'voided') THEN
    RAISE EXCEPTION 'cancelled_document'
      USING ERRCODE = '22023',
            MESSAGE = 'Ləğv edilmiş sənəd təsdiqlənə bilməz';
  END IF;

  IF COALESCE(v_sale.total_amount, 0) <= 0 THEN
    RAISE EXCEPTION 'invalid_total_amount'
      USING ERRCODE = '22023',
            MESSAGE = 'Satış məbləği sıfırdan böyük olmalıdır';
  END IF;

  IF COALESCE(v_sale.paid_amount, 0) > COALESCE(v_sale.total_amount, 0) + 0.0001 THEN
    RAISE EXCEPTION 'overpaid'
      USING ERRCODE = '22023',
            MESSAGE = 'Ödənilən məbləğ ümumi məbləğdən böyük ola bilməz';
  END IF;

  SELECT COALESCE(jsonb_agg(item_json ORDER BY ord), '[]'::jsonb)
  INTO v_items
  FROM (
    SELECT
      row_number() OVER (ORDER BY id) AS ord,
      jsonb_build_object(
        'product_id', product_id,
        'quantity', quantity,
        'warehouse_id', warehouse_id,
        'polywood_sale_mode', polywood_sale_mode,
        'polywood_length_m', polywood_length_m,
        'skip_stock', (polywood_sale_mode IS NOT NULL AND btrim(polywood_sale_mode) <> '')
      ) AS item_json
    FROM sale_items
    WHERE sale_id = p_sale_id
  ) lined;

  IF jsonb_array_length(v_items) = 0 THEN
    RAISE EXCEPTION 'items_required'
      USING ERRCODE = '22023',
            MESSAGE = 'Ən azı bir satış sətri tələb olunur';
  END IF;

  -- Stock deduction is handled by trg_sales_posted_inventory when status becomes posted.
  -- Pre-validate demand so posting fails before side effects if stock is insufficient.
  PERFORM public.build_and_validate_sale_stock_demand(v_items);

  v_idempotency := 'sale_invoice:' || p_sale_id::text;
  v_cogs_result := public.process_sale_fifo_cogs(
    p_sale_id,
    v_sale.doc_no,
    v_idempotency || ':cogs'
  );
  v_total_cogs := COALESCE((v_cogs_result->>'total_cogs')::numeric, 0);
  v_cogs_journal_id := NULLIF(v_cogs_result->>'cogs_journal_entry_id', '')::uuid;

  v_payments := COALESCE(v_sale.payments, '[]'::jsonb);
  IF jsonb_typeof(v_payments) = 'array' THEN
    FOR v_pay IN SELECT value FROM jsonb_array_elements(v_payments)
    LOOP
      v_pay_amount := COALESCE(NULLIF(v_pay->>'amount', '')::numeric, 0);
      IF v_pay_amount <= 0 THEN
        CONTINUE;
      END IF;

      v_account_id := NULLIF(v_pay->>'account_id', '')::uuid;
      IF v_account_id IS NULL THEN
        RAISE EXCEPTION 'account_required'
          USING ERRCODE = '22023',
                MESSAGE = 'Ödəniş üçün kassa/bank hesabı seçilməlidir';
      END IF;

      PERFORM id FROM accounts WHERE id = v_account_id;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'account_not_found'
          USING ERRCODE = 'P0002',
                MESSAGE = 'Seçilmiş kassa/bank hesabı tapılmadı';
      END IF;

      v_pay_method := COALESCE(NULLIF(trim(v_pay->>'method'), ''), 'Ödəniş');
      PERFORM public.post_cash_transaction(
        v_account_id,
        'Mədaxil',
        v_pay_amount,
        'Satış Ödənişi',
        format('Satış fakturası %s — %s', v_sale.doc_no, v_pay_method),
        NULL,
        'sale',
        p_sale_id
      );
    END LOOP;
  END IF;

  v_add_exp_total := public.apply_document_additional_expenses(
    COALESCE(v_sale.additional_expenses, '[]'::jsonb),
    'sale',
    p_sale_id,
    v_sale.doc_no
  );

  v_journal_id := public.post_sale_invoice_gl_journal(
    p_sale_id,
    v_sale.doc_no,
    v_sale.total_amount,
    v_sale.customer_id,
    v_idempotency
  );

  UPDATE sales
  SET status = 'posted',
      posted_at = NOW(),
      additional_expenses_total = v_add_exp_total
  WHERE id = p_sale_id;

  PERFORM public.refresh_customer_ar_balance(v_sale.customer_id);

  v_result := jsonb_build_object(
    'success', true,
    'event_type', 'sales_invoice_post',
    'sale_id', p_sale_id,
    'doc_no', v_sale.doc_no,
    'status', 'posted',
    'journal_entry_id', v_journal_id,
    'cogs_journal_entry_id', v_cogs_journal_id,
    'total_cogs', v_total_cogs,
    'total_amount', v_sale.total_amount,
    'paid_amount', v_sale.paid_amount,
    'remaining_balance', v_sale.remaining_balance
  );

  -- log_erp_event takes seven arguments:
  --   (p_event_type TEXT, p_source_table TEXT, p_source_id UUID, p_payload JSONB,
  --    p_journal_entry_id UUID, p_idempotency_key TEXT, p_result JSONB)
  -- The phase-4 rewrite passed six in the wrong order, so every attempt to post a
  -- sales invoice failed with:
  --   function public.log_erp_event(unknown, unknown, uuid, unknown, jsonb, uuid) does not exist
  -- PL/pgSQL resolves the call only when it runs, which is why this shipped.
  v_event_id := public.log_erp_event(
    'sales_invoice',
    'sales',
    p_sale_id,
    jsonb_build_object('sale_id', p_sale_id, 'posted_from', 'draft', 'posted_by', auth.uid()),
    COALESCE(v_cogs_journal_id, v_journal_id),
    v_idempotency,
    v_result
  );

  RETURN v_result || jsonb_build_object('event_id', v_event_id);
END;
$function$;

CREATE OR REPLACE FUNCTION public.process_sale_fifo_cogs(p_sale_id uuid, p_doc_no text DEFAULT NULL::text, p_idempotency text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_item RECORD;
  v_line_cogs NUMERIC;
  v_total_cogs NUMERIC := 0;
  v_cogs_journal_id UUID;
  v_doc_no TEXT;
BEGIN
  IF p_sale_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'sale_id tələb olunur';
  END IF;

  SELECT COALESCE(NULLIF(trim(doc_no), ''), id::text)
  INTO v_doc_no
  FROM public.sales
  WHERE id = p_sale_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'sale_not_found' USING ERRCODE = 'P0002', MESSAGE = 'Satış tapılmadı';
  END IF;

  v_doc_no := COALESCE(NULLIF(trim(p_doc_no), ''), v_doc_no);

  FOR v_item IN
    SELECT si.id, si.product_id, si.quantity, si.polywood_sale_mode,
           COALESCE(p.is_service, false) AS is_service
    FROM public.sale_items si
    LEFT JOIN public.products p ON p.id = si.product_id
    WHERE si.sale_id = p_sale_id
    ORDER BY si.id
    FOR UPDATE OF si
  LOOP
    IF v_item.product_id IS NULL OR COALESCE(v_item.quantity, 0) <= 0 THEN
      CONTINUE;
    END IF;

    IF v_item.polywood_sale_mode IS NOT NULL THEN
      CONTINUE;
    END IF;

    -- Services have no cost layer.
    IF v_item.is_service THEN
      CONTINUE;
    END IF;

    v_line_cogs := public.fifo_deplete_sale_item(
      v_item.id,
      v_item.product_id,
      v_item.quantity,
      p_sale_id
    );

    UPDATE public.sale_items
    SET cogs_amount = v_line_cogs
    WHERE id = v_item.id;

    v_total_cogs := v_total_cogs + v_line_cogs;
  END LOOP;

  v_total_cogs := ROUND(v_total_cogs, 2);
  v_cogs_journal_id := public.post_sale_cogs_journal(
    p_sale_id,
    v_doc_no,
    v_total_cogs,
    COALESCE(p_idempotency, 'sale_cogs:' || p_sale_id::text)
  );

  UPDATE public.sales
  SET total_cogs = v_total_cogs,
      cogs_journal_entry_id = v_cogs_journal_id
  WHERE id = p_sale_id;

  RETURN jsonb_build_object(
    'total_cogs', v_total_cogs,
    'cogs_journal_entry_id', v_cogs_journal_id
  );
END;
$function$;

CREATE OR REPLACE FUNCTION public.process_sales_invoice_event(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_idempotency TEXT;
  v_cached JSONB;
  v_header JSONB;
  v_items JSONB;
  v_payments JSONB;
  v_decrement_stock BOOLEAN := true;
  v_customer_id UUID;
  v_customer_name TEXT;
  v_sale_id UUID;
  v_doc_no TEXT;
  v_total_amount NUMERIC;
  v_paid_amount NUMERIC;
  v_remaining NUMERIC;
  v_item JSONB;
  v_pay JSONB;
  v_product_id UUID;
  v_qty NUMERIC;
  v_stock NUMERIC;
  v_account_id UUID;
  v_pay_amount NUMERIC;
  v_pay_method TEXT;
  v_skip_stock BOOLEAN;
  v_polywood_mode TEXT;
  v_polywood_sale_mode TEXT;
  v_polywood_length_m NUMERIC;
  v_item_ids JSONB := '[]'::jsonb;
  v_item_id UUID;
  v_idx INT := 0;
  v_stock_demand JSONB := '{}'::jsonb;
  v_key TEXT;
  v_journal_id UUID;
  v_cogs_result JSONB;
  v_total_cogs NUMERIC := 0;
  v_cogs_journal_id UUID;
  v_event_id UUID;
  v_result JSONB;
  v_add_exp_total NUMERIC;
BEGIN
  IF p_payload IS NULL THEN
    RAISE EXCEPTION 'invalid_payload'
      USING ERRCODE = '22023',
            MESSAGE = 'Satış event payload göndərilməyib';
  END IF;

  v_idempotency := NULLIF(trim(p_payload->>'idempotency_key'), '');
  IF v_idempotency IS NOT NULL THEN
    v_cached := public.find_erp_event_by_idempotency(v_idempotency);
    IF v_cached IS NOT NULL THEN
      RETURN v_cached->'result';
    END IF;
  END IF;

  IF NOT (
    public.require_permission('can_edit_sales')
    OR public.require_permission('can_create_invoice')
    OR public.require_permission('can_manage_finance')
  ) THEN
    RAISE EXCEPTION 'forbidden'
      USING ERRCODE = '42501',
            MESSAGE = 'Satış yaratmaq üçün icazəniz yoxdur';
  END IF;

  v_header := COALESCE(p_payload->'header', '{}'::jsonb);
  v_items := COALESCE(p_payload->'items', '[]'::jsonb);
  v_payments := COALESCE(p_payload->'payments', '[]'::jsonb);

  IF jsonb_typeof(v_items) <> 'array' OR jsonb_array_length(v_items) = 0 THEN
    RAISE EXCEPTION 'items_required'
      USING ERRCODE = '22023',
            MESSAGE = 'Æn azı bir satış sətri tələb olunur';
  END IF;

  IF (p_payload ? 'decrement_stock') THEN
    v_decrement_stock := COALESCE((p_payload->>'decrement_stock')::boolean, true);
  END IF;

  v_customer_id := NULLIF(v_header->>'customer_id', '')::uuid;
  IF v_customer_id IS NULL THEN
    RAISE EXCEPTION 'customer_required'
      USING ERRCODE = '22023',
            MESSAGE = 'Müştəri seçilməlidir';
  END IF;

  SELECT COALESCE(NULLIF(trim(full_name), ''), NULLIF(trim(name), ''), NULLIF(trim(company_name), ''), '')
  INTO v_customer_name
  FROM customers
  WHERE id = v_customer_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'customer_not_found'
      USING ERRCODE = 'P0002',
            MESSAGE = 'Müştəri tapılmadı';
  END IF;

  v_total_amount := COALESCE(NULLIF(v_header->>'total_amount', '')::numeric, 0);
  v_paid_amount := COALESCE(NULLIF(v_header->>'paid_amount', '')::numeric, 0);
  v_remaining := GREATEST(
    COALESCE(NULLIF(v_header->>'remaining_balance', '')::numeric, v_total_amount - v_paid_amount),
    0
  );

  IF v_total_amount <= 0 THEN
    RAISE EXCEPTION 'invalid_total_amount'
      USING ERRCODE = '22023',
            MESSAGE = 'Satış məbləği sıfırdan böyük olmalıdır';
  END IF;

  IF v_paid_amount > v_total_amount + 0.0001 THEN
    RAISE EXCEPTION 'overpaid'
      USING ERRCODE = '22023',
            MESSAGE = 'Ödənilən məbləğ ümumi məbləğdən böyük ola bilməz';
  END IF;

  IF v_decrement_stock THEN
    v_stock_demand := public.build_and_validate_sale_stock_demand(v_items);
  END IF;

  IF jsonb_typeof(v_payments) = 'array' THEN
    FOR v_pay IN SELECT value FROM jsonb_array_elements(v_payments)
    LOOP
      v_pay_amount := COALESCE(NULLIF(v_pay->>'amount', '')::numeric, 0);
      IF v_pay_amount <= 0 THEN
        CONTINUE;
      END IF;

      v_account_id := NULLIF(v_pay->>'account_id', '')::uuid;
      IF v_account_id IS NULL THEN
        RAISE EXCEPTION 'account_required'
          USING ERRCODE = '22023',
                MESSAGE = 'Ödəniş üçün kassa/bank hesabı seçilməlidir';
      END IF;

      PERFORM id FROM accounts WHERE id = v_account_id;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'account_not_found'
          USING ERRCODE = 'P0002',
                MESSAGE = 'Seçilmiş kassa/bank hesabı tapılmadı';
      END IF;
    END LOOP;
  END IF;

  v_doc_no := NULLIF(trim(v_header->>'doc_no'), '');
  IF v_doc_no IS NULL THEN
    v_doc_no := 'SF-' || to_char(CURRENT_DATE, 'YYYY') || '-' || floor(10000 + random() * 90000)::int;
  END IF;

  INSERT INTO sales (
    doc_no, invoice_number, doc_date, customer_id, customer_name,
    seller_id, seller_name, warehouse_name, subtotal, discount_total, vat_total,
    total_amount, paid_amount, remaining_balance, delivery_address, delivery_type,
    delivery_fee, note, notes, payments, created_at
  )
  VALUES (
    v_doc_no,
    COALESCE(NULLIF(trim(v_header->>'invoice_number'), ''), v_doc_no),
    COALESCE(NULLIF(v_header->>'doc_date', '')::date, CURRENT_DATE),
    v_customer_id,
    COALESCE(NULLIF(trim(v_header->>'customer_name'), ''), v_customer_name),
    NULLIF(v_header->>'seller_id', '')::uuid,
    NULLIF(trim(v_header->>'seller_name'), ''),
    NULLIF(trim(v_header->>'warehouse_name'), ''),
    COALESCE(NULLIF(v_header->>'subtotal', '')::numeric, 0),
    COALESCE(NULLIF(v_header->>'discount_total', '')::numeric, 0),
    COALESCE(NULLIF(v_header->>'vat_total', '')::numeric, 0),
    v_total_amount,
    v_paid_amount,
    v_remaining,
    NULLIF(trim(v_header->>'delivery_address'), ''),
    COALESCE(NULLIF(trim(v_header->>'delivery_type'), ''), 'free'),
    COALESCE(NULLIF(v_header->>'delivery_fee', '')::numeric, 0),
    NULLIF(trim(v_header->>'note'), ''),
    NULLIF(trim(v_header->>'notes'), ''),
    COALESCE(v_header->'payments', v_payments, '[]'::jsonb),
    COALESCE(NULLIF(v_header->>'created_at', '')::timestamptz, NOW())
  )
  RETURNING id INTO v_sale_id;

  FOR v_item IN SELECT value FROM jsonb_array_elements(v_items)
  LOOP
    v_polywood_sale_mode := CASE
      WHEN v_item ? 'polywood_sale_mode'
      THEN NULLIF(trim(v_item->>'polywood_sale_mode'), '')
      ELSE NULL
    END;

    v_polywood_length_m := NULL;
    IF v_item ? 'polywood_length_m' THEN
      BEGIN
        v_polywood_length_m := NULLIF(trim(v_item->>'polywood_length_m'), '')::numeric;
      EXCEPTION
        WHEN OTHERS THEN
          v_polywood_length_m := NULL;
      END;
    END IF;

    INSERT INTO sale_items (
      sale_id, product_id, product_code, product_name, warehouse_id, warehouse_name,
      quantity, unit, unit_price, discount_percent, vat_rate, line_total, extra_info,
      polywood_sale_mode, polywood_length_m
    )
    VALUES (
      v_sale_id,
      NULLIF(v_item->>'product_id', '')::uuid,
      NULLIF(trim(v_item->>'product_code'), ''),
      NULLIF(trim(v_item->>'product_name'), ''),
      NULLIF(v_item->>'warehouse_id', '')::uuid,
      NULLIF(trim(v_item->>'warehouse_name'), ''),
      COALESCE(NULLIF(v_item->>'quantity', '')::numeric, 0),
      COALESCE(NULLIF(trim(v_item->>'unit'), ''), 'Ædəd'),
      COALESCE(NULLIF(v_item->>'unit_price', '')::numeric, 0),
      COALESCE(NULLIF(v_item->>'discount_percent', '')::numeric, 0),
      COALESCE(NULLIF(v_item->>'vat_rate', '')::numeric, 0),
      COALESCE(NULLIF(v_item->>'line_total', '')::numeric, NULLIF(v_item->>'total', '')::numeric, 0),
      NULLIF(trim(v_item->>'extra_info'), ''),
      v_polywood_sale_mode,
      v_polywood_length_m
    )
    RETURNING id INTO v_item_id;

    v_item_ids := v_item_ids || jsonb_build_array(
      jsonb_build_object(
        'index', v_idx,
        'id', v_item_id,
        'product_id', NULLIF(v_item->>'product_id', '')::uuid,
        'polywood_sale_mode', v_polywood_sale_mode
      )
    );
    v_idx := v_idx + 1;
  END LOOP;

  IF v_decrement_stock THEN
    PERFORM public.apply_sale_stock_decrement(v_stock_demand);

    v_cogs_result := public.process_sale_fifo_cogs(
      v_sale_id,
      v_doc_no,
      COALESCE(v_idempotency, 'sale_invoice:' || v_sale_id::text) || ':cogs'
    );
    v_total_cogs := COALESCE((v_cogs_result->>'total_cogs')::numeric, 0);
    v_cogs_journal_id := NULLIF(v_cogs_result->>'cogs_journal_entry_id', '')::uuid;
  END IF;

  IF jsonb_typeof(v_payments) = 'array' THEN
    FOR v_pay IN SELECT value FROM jsonb_array_elements(v_payments)
    LOOP
      v_pay_amount := COALESCE(NULLIF(v_pay->>'amount', '')::numeric, 0);
      IF v_pay_amount <= 0 THEN
        CONTINUE;
      END IF;

      v_account_id := NULLIF(v_pay->>'account_id', '')::uuid;
      v_pay_method := COALESCE(NULLIF(trim(v_pay->>'method'), ''), 'Ödəniş');

      PERFORM public.post_cash_transaction(
        v_account_id,
        'Mədaxil',
        v_pay_amount,
        'Satış Ödənişi',
        format('Satış fakturası %s — %s', v_doc_no, v_pay_method),
        NULL,
        'sale',
        v_sale_id
      );
    END LOOP;
  END IF;

  v_add_exp_total := public.apply_document_additional_expenses(
    COALESCE(p_payload->'additional_expenses', '[]'::jsonb),
    'sale',
    v_sale_id,
    v_doc_no
  );

  UPDATE sales
  SET additional_expenses = COALESCE(p_payload->'additional_expenses', '[]'::jsonb),
      additional_expenses_total = v_add_exp_total
  WHERE id = v_sale_id;

  v_journal_id := public.post_sale_invoice_gl_journal(
    v_sale_id,
    v_doc_no,
    v_total_amount,
    v_customer_id,
    v_idempotency
  );

  PERFORM public.refresh_customer_ar_balance(v_customer_id);

  v_result := jsonb_build_object(
    'success', true,
    'event_type', 'sales_invoice',
    'sale_id', v_sale_id,
    'doc_no', v_doc_no,
    'items', v_item_ids,
    'journal_entry_id', v_journal_id,
    'cogs_journal_entry_id', v_cogs_journal_id,
    'total_cogs', v_total_cogs,
    'total_amount', v_total_amount,
    'paid_amount', v_paid_amount,
    'remaining_balance', v_remaining
  );

  v_event_id := public.log_erp_event(
    'sales_invoice',
    'sales',
    v_sale_id,
    p_payload,
    COALESCE(v_cogs_journal_id, v_journal_id),
    v_idempotency,
    v_result
  );

  v_result := v_result || jsonb_build_object('event_id', v_event_id);
  RETURN v_result;
END;
$function$;

CREATE OR REPLACE FUNCTION public.restore_sale_stock(p_sale_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_item RECORD;
  v_qty NUMERIC;
  v_restored INT := 0;
BEGIN
  FOR v_item IN
    SELECT product_id, quantity, polywood_sale_mode
    FROM sale_items
    WHERE sale_id = p_sale_id
  LOOP
    IF v_item.product_id IS NULL THEN
      CONTINUE;
    END IF;
    IF NULLIF(trim(COALESCE(v_item.polywood_sale_mode, '')), '') IS NOT NULL THEN
      CONTINUE;
    END IF;

    v_qty := COALESCE(v_item.quantity, 0);
    IF v_qty <= 0 THEN
      CONTINUE;
    END IF;

    UPDATE products
    SET stock = COALESCE(stock, 0) + v_qty
    WHERE id = v_item.product_id;

    v_restored := v_restored + 1;
  END LOOP;

  RETURN v_restored;
END;
$function$;

CREATE OR REPLACE FUNCTION public.sales_doc_serial(p_value text)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT CASE
    WHEN p_value ~ '^[A-Za-z]+-[0-9]{4}-[0-9]+$'
      THEN NULLIF(substring(p_value from '[0-9]+$'), '')::INT
    ELSE NULL
  END;
$function$;

CREATE OR REPLACE FUNCTION public.save_sales_invoice_draft(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_header JSONB;
  v_items JSONB;
  v_payments JSONB;
  v_sale_id UUID;
  v_doc_no TEXT;
  v_customer_id UUID;
  v_customer_name TEXT;
  v_prefix TEXT;
  v_item JSONB;
  v_status TEXT;
  v_item_ids JSONB := '[]'::jsonb;
  v_item_id UUID;
  v_idx INT := 0;
  v_add_exp JSONB;
BEGIN
  IF p_payload IS NULL THEN
    RAISE EXCEPTION 'invalid_payload'
      USING ERRCODE = '22023',
            MESSAGE = 'Satış draft payload göndərilməyib';
  END IF;

  IF NOT (
    public.require_permission('can_edit_sales')
    OR public.require_permission('can_create_invoice')
    OR public.require_permission('can_manage_finance')
  ) THEN
    RAISE EXCEPTION 'forbidden'
      USING ERRCODE = '42501',
            MESSAGE = 'Satış yaratmaq üçün icazəniz yoxdur';
  END IF;

  v_header := COALESCE(p_payload->'header', '{}'::jsonb);
  v_items := COALESCE(p_payload->'items', '[]'::jsonb);
  v_payments := COALESCE(p_payload->'payments', '[]'::jsonb);
  v_add_exp := COALESCE(p_payload->'additional_expenses', '[]'::jsonb);
  v_sale_id := NULLIF(p_payload->>'sale_id', '')::uuid;
  IF v_sale_id IS NULL THEN
    v_sale_id := NULLIF(v_header->>'id', '')::uuid;
  END IF;

  IF jsonb_typeof(v_items) <> 'array' OR jsonb_array_length(v_items) = 0 THEN
    RAISE EXCEPTION 'items_required'
      USING ERRCODE = '22023',
            MESSAGE = 'Ən azı bir satış sətri tələb olunur';
  END IF;

  v_customer_id := NULLIF(v_header->>'customer_id', '')::uuid;
  IF v_customer_id IS NULL THEN
    RAISE EXCEPTION 'customer_required'
      USING ERRCODE = '22023',
            MESSAGE = 'Müştəri seçilməlidir';
  END IF;

  SELECT COALESCE(NULLIF(trim(full_name), ''), NULLIF(trim(name), ''), NULLIF(trim(company_name), ''), '')
  INTO v_customer_name
  FROM customers
  WHERE id = v_customer_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'customer_not_found'
      USING ERRCODE = 'P0002',
            MESSAGE = 'Müştəri tapılmadı';
  END IF;

  IF v_sale_id IS NOT NULL THEN
    SELECT status, doc_no INTO v_status, v_doc_no
    FROM sales
    WHERE id = v_sale_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'sale_not_found'
        USING ERRCODE = 'P0002',
              MESSAGE = 'Satış sənədi tapılmadı';
    END IF;

    IF v_status = 'posted' THEN
      RAISE EXCEPTION 'already_posted'
        USING ERRCODE = '22023',
              MESSAGE = 'Təsdiqlənmiş sənəd redaktə edilə bilməz';
    END IF;

    IF v_status IN ('cancelled', 'void', 'voided') THEN
      RAISE EXCEPTION 'cancelled_document'
        USING ERRCODE = '22023',
              MESSAGE = 'Ləğv edilmiş sənəd redaktə edilə bilməz';
    END IF;
  ELSE
    v_doc_no := NULLIF(trim(v_header->>'doc_no'), '');
    v_prefix := CASE
      WHEN COALESCE(v_header->>'invoice_mode', '') = 'polywood' THEN 'SPW'
      ELSE 'SS'
    END;
    IF v_doc_no IS NULL OR v_doc_no ~ '\.{3,}$' THEN
      v_doc_no := public.next_sales_doc_no(v_prefix);
    END IF;
  END IF;

  IF v_sale_id IS NULL THEN
    INSERT INTO sales (
      doc_no, invoice_number, doc_date, customer_id, customer_name,
      seller_id, seller_name, warehouse_name, subtotal, discount_total, vat_total,
      total_amount, paid_amount, remaining_balance, delivery_address, delivery_type,
      delivery_fee, note, notes, payments, created_at, status, payment_type,
      due_date, currency, exchange_rate, currency_breakdown, additional_expenses,
      additional_expenses_total
    )
    VALUES (
      v_doc_no,
      COALESCE(NULLIF(trim(v_header->>'invoice_number'), ''), v_doc_no),
      COALESCE(NULLIF(v_header->>'doc_date', '')::date, CURRENT_DATE),
      v_customer_id,
      COALESCE(NULLIF(trim(v_header->>'customer_name'), ''), v_customer_name),
      NULLIF(v_header->>'seller_id', '')::uuid,
      NULLIF(trim(v_header->>'seller_name'), ''),
      NULLIF(trim(v_header->>'warehouse_name'), ''),
      COALESCE(NULLIF(v_header->>'subtotal', '')::numeric, 0),
      COALESCE(NULLIF(v_header->>'discount_total', '')::numeric, 0),
      COALESCE(NULLIF(v_header->>'vat_total', '')::numeric, 0),
      COALESCE(NULLIF(v_header->>'total_amount', '')::numeric, 0),
      COALESCE(NULLIF(v_header->>'paid_amount', '')::numeric, 0),
      GREATEST(COALESCE(NULLIF(v_header->>'remaining_balance', '')::numeric, 0), 0),
      NULLIF(trim(v_header->>'delivery_address'), ''),
      COALESCE(NULLIF(trim(v_header->>'delivery_type'), ''), 'free'),
      COALESCE(NULLIF(v_header->>'delivery_fee', '')::numeric, 0),
      NULLIF(trim(v_header->>'note'), ''),
      NULLIF(trim(v_header->>'notes'), ''),
      COALESCE(v_header->'payments', v_payments, '[]'::jsonb),
      COALESCE(NULLIF(v_header->>'created_at', '')::timestamptz, NOW()),
      'draft',
      COALESCE(NULLIF(trim(v_header->>'payment_type'), ''), 'cash'),
      NULLIF(v_header->>'due_date', '')::date,
      COALESCE(NULLIF(trim(v_header->>'currency'), ''), 'AZN'),
      COALESCE(NULLIF(v_header->>'exchange_rate', '')::numeric, 1),
      COALESCE(v_header->'currency_breakdown', '{}'::jsonb),
      v_add_exp,
      COALESCE(NULLIF(v_header->>'additional_expenses_total', '')::numeric, 0)
    )
    RETURNING id INTO v_sale_id;
  ELSE
    UPDATE sales SET
      doc_date = COALESCE(NULLIF(v_header->>'doc_date', '')::date, doc_date),
      customer_id = v_customer_id,
      customer_name = COALESCE(NULLIF(trim(v_header->>'customer_name'), ''), v_customer_name),
      seller_id = NULLIF(v_header->>'seller_id', '')::uuid,
      seller_name = NULLIF(trim(v_header->>'seller_name'), ''),
      warehouse_name = NULLIF(trim(v_header->>'warehouse_name'), ''),
      subtotal = COALESCE(NULLIF(v_header->>'subtotal', '')::numeric, 0),
      discount_total = COALESCE(NULLIF(v_header->>'discount_total', '')::numeric, 0),
      vat_total = COALESCE(NULLIF(v_header->>'vat_total', '')::numeric, 0),
      total_amount = COALESCE(NULLIF(v_header->>'total_amount', '')::numeric, 0),
      paid_amount = COALESCE(NULLIF(v_header->>'paid_amount', '')::numeric, 0),
      remaining_balance = GREATEST(COALESCE(NULLIF(v_header->>'remaining_balance', '')::numeric, 0), 0),
      delivery_address = NULLIF(trim(v_header->>'delivery_address'), ''),
      delivery_type = COALESCE(NULLIF(trim(v_header->>'delivery_type'), ''), 'free'),
      delivery_fee = COALESCE(NULLIF(v_header->>'delivery_fee', '')::numeric, 0),
      note = NULLIF(trim(v_header->>'note'), ''),
      notes = NULLIF(trim(v_header->>'notes'), ''),
      payments = COALESCE(v_header->'payments', v_payments, '[]'::jsonb),
      status = 'draft',
      payment_type = COALESCE(NULLIF(trim(v_header->>'payment_type'), ''), payment_type, 'cash'),
      due_date = NULLIF(v_header->>'due_date', '')::date,
      currency = COALESCE(NULLIF(trim(v_header->>'currency'), ''), currency, 'AZN'),
      exchange_rate = COALESCE(NULLIF(v_header->>'exchange_rate', '')::numeric, exchange_rate, 1),
      currency_breakdown = COALESCE(v_header->'currency_breakdown', currency_breakdown, '{}'::jsonb),
      additional_expenses = v_add_exp,
      additional_expenses_total = COALESCE(NULLIF(v_header->>'additional_expenses_total', '')::numeric, 0)
    WHERE id = v_sale_id;

    DELETE FROM sale_items WHERE sale_id = v_sale_id;
  END IF;

  FOR v_item IN SELECT value FROM jsonb_array_elements(v_items)
  LOOP
    INSERT INTO sale_items (
      sale_id, product_id, product_code, product_name, warehouse_id, warehouse_name,
      quantity, unit, unit_price, discount_percent, discount_type, vat_rate, line_total, extra_info,
      polywood_sale_mode, polywood_length_m, price_tier, currency, exchange_rate
    )
    VALUES (
      v_sale_id,
      NULLIF(v_item->>'product_id', '')::uuid,
      NULLIF(trim(v_item->>'product_code'), ''),
      NULLIF(trim(v_item->>'product_name'), ''),
      NULLIF(v_item->>'warehouse_id', '')::uuid,
      NULLIF(trim(v_item->>'warehouse_name'), ''),
      COALESCE(NULLIF(v_item->>'quantity', '')::numeric, 0),
      COALESCE(NULLIF(trim(v_item->>'unit'), ''), 'Ədəd'),
      COALESCE(NULLIF(v_item->>'unit_price', '')::numeric, 0),
      COALESCE(NULLIF(v_item->>'discount_percent', '')::numeric, 0),
      CASE
        WHEN COALESCE(NULLIF(trim(v_item->>'discount_type'), ''), 'percentage') = 'fixed' THEN 'fixed'
        ELSE 'percentage'
      END,
      COALESCE(NULLIF(v_item->>'vat_rate', '')::numeric, 0),
      COALESCE(NULLIF(v_item->>'line_total', '')::numeric, NULLIF(v_item->>'total', '')::numeric, 0),
      NULLIF(trim(v_item->>'extra_info'), ''),
      NULLIF(trim(v_item->>'polywood_sale_mode'), ''),
      NULLIF(trim(v_item->>'polywood_length_m'), '')::numeric,
      COALESCE(NULLIF(trim(v_item->>'price_tier'), ''), 'retail'),
      COALESCE(NULLIF(trim(v_item->>'currency'), ''), 'AZN'),
      COALESCE(NULLIF(v_item->>'exchange_rate', '')::numeric, 1)
    )
    RETURNING id INTO v_item_id;

    v_item_ids := v_item_ids || jsonb_build_array(
      jsonb_build_object(
        'index', v_idx,
        'id', v_item_id,
        'product_id', NULLIF(v_item->>'product_id', '')::uuid,
        'polywood_sale_mode', NULLIF(trim(v_item->>'polywood_sale_mode'), '')
      )
    );
    v_idx := v_idx + 1;
  END LOOP;

  RETURN jsonb_build_object(
    'success', true,
    'event_type', 'sales_invoice_draft',
    'sale_id', v_sale_id,
    'doc_no', v_doc_no,
    'status', 'draft',
    'items', v_item_ids
  );
END;
$function$;

CREATE OR REPLACE FUNCTION public.void_sale_atomic(p_sale_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_sale sales%ROWTYPE;
  v_note TEXT;
  v_doc_label TEXT;
  v_tx_deleted INT;
  v_stock_restored INT;
BEGIN
  IF NOT public.require_permission('can_delete_sales')
     AND NOT public.require_permission('can_edit_sales') THEN
    RAISE EXCEPTION 'forbidden'
      USING ERRCODE = '42501',
            MESSAGE = 'Satış ləğvi üçün icazəniz yoxdur';
  END IF;

  SELECT * INTO v_sale
  FROM sales
  WHERE id = p_sale_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'sale_not_found'
      USING ERRCODE = 'P0002',
            MESSAGE = 'Satış fakturası tapılmadı';
  END IF;

  IF public.is_invoice_cancelled(v_sale.status) THEN
    RETURN jsonb_build_object(
      'sale_id', p_sale_id,
      'already_void', true,
      'status', v_sale.status
    );
  END IF;

  v_doc_label := COALESCE(NULLIF(trim(v_sale.doc_no), ''), NULLIF(trim(v_sale.invoice_number), ''), p_sale_id::text);
  v_note := trim(COALESCE(p_reason, ''));
  IF v_note = '' THEN
    v_note := 'Satış fakturası ləğv edildi';
  END IF;

  v_stock_restored := public.restore_sale_stock(p_sale_id);
  v_tx_deleted := public.delete_document_cash_transactions('sale', p_sale_id, v_doc_label);

  UPDATE warehouse_slips
  SET status = 'rejected'
  WHERE source_type = 'sale'
    AND source_document_id = p_sale_id
    AND status = 'pending';

  UPDATE sales
  SET
    status = 'cancelled',
    paid_amount = 0,
    remaining_balance = 0,
    payments = '[]'::jsonb,
    warehouse_sent = FALSE,
    warehouse_slip_status = NULL,
    note = COALESCE(note, v_note),
    notes = CASE
      WHEN notes IS NULL OR trim(notes) = '' THEN v_note
      ELSE notes || E'\n' || v_note
    END
  WHERE id = p_sale_id;

  IF v_sale.customer_id IS NOT NULL THEN
    PERFORM public.refresh_customer_ar_balance(v_sale.customer_id);
  END IF;

  RETURN jsonb_build_object(
    'sale_id', p_sale_id,
    'already_void', false,
    'status', 'cancelled',
    'stock_lines_restored', v_stock_restored,
    'transactions_removed', v_tx_deleted
  );
END;
$function$;

CREATE OR REPLACE FUNCTION public.void_sale_invoice(p_sale_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
    -- حذف تراکنش‌های مالی متصل به این فاکتور
    DELETE FROM transactions WHERE sale_id = p_sale_id;
    
    -- حذف حرکات انبار مرتبط با این فاکتور
    DELETE FROM stock_movements WHERE sale_id = p_sale_id;
    
    -- تغییر وضعیت فاکتور به لغو شده
    UPDATE sales 
    SET status = 'cancelled', 
        updated_at = NOW() 
    WHERE id = p_sale_id;
END;
$function$;


-- -- grants ------------------------------------------------------
revoke all on function public.cancel_sales_invoice_atomic(p_sale_id uuid, p_reason text) from public, anon, authenticated, service_role;
grant execute on function public.cancel_sales_invoice_atomic(p_sale_id uuid, p_reason text) to authenticated;
grant execute on function public.cancel_sales_invoice_atomic(p_sale_id uuid, p_reason text) to service_role;
revoke all on function public.create_sale_atomic(p_payload jsonb) from public, anon, authenticated, service_role;
grant execute on function public.create_sale_atomic(p_payload jsonb) to public;
grant execute on function public.create_sale_atomic(p_payload jsonb) to anon;
grant execute on function public.create_sale_atomic(p_payload jsonb) to authenticated;
grant execute on function public.create_sale_atomic(p_payload jsonb) to service_role;
revoke all on function public.fifo_deplete_sale_item(p_sale_item_id uuid, p_product_id uuid, p_quantity numeric, p_sale_id uuid) from public, anon, authenticated, service_role;
grant execute on function public.fifo_deplete_sale_item(p_sale_item_id uuid, p_product_id uuid, p_quantity numeric, p_sale_id uuid) to public;
grant execute on function public.fifo_deplete_sale_item(p_sale_item_id uuid, p_product_id uuid, p_quantity numeric, p_sale_id uuid) to anon;
grant execute on function public.fifo_deplete_sale_item(p_sale_item_id uuid, p_product_id uuid, p_quantity numeric, p_sale_id uuid) to authenticated;
grant execute on function public.fifo_deplete_sale_item(p_sale_item_id uuid, p_product_id uuid, p_quantity numeric, p_sale_id uuid) to service_role;
revoke all on function public.next_sales_doc_no(p_prefix text) from public, anon, authenticated, service_role;
grant execute on function public.next_sales_doc_no(p_prefix text) to public;
grant execute on function public.next_sales_doc_no(p_prefix text) to anon;
grant execute on function public.next_sales_doc_no(p_prefix text) to authenticated;
grant execute on function public.next_sales_doc_no(p_prefix text) to service_role;
revoke all on function public.peek_next_sales_doc_no(p_prefix text) from public, anon, authenticated, service_role;
grant execute on function public.peek_next_sales_doc_no(p_prefix text) to public;
grant execute on function public.peek_next_sales_doc_no(p_prefix text) to anon;
